+.footer a{display:block;padding:4px 0;color:var(--muted)}
+.footer a:hover{color:#fff}
+
+.pill{
+  display:inline-flex;align-items:center;gap:8px;
+  padding:8px 10px;border-radius:999px;
+  border:1px solid var(--stroke);
+  background:rgba(255,255,255,.04);
+  color:var(--muted);
+  font-weight:800;font-size:12px;
+}
+
+.split{display:grid;grid-template-columns:1fr 1fr;gap:14px}
+
+.ideaCard{padding:12px;border-radius:14px;border:1px solid var(--stroke);background:rgba(8,12,20,.35)}
+.ideaCard__top{display:flex;align-items:center;justify-content:space-between;gap:10px}
+.ideaCard .title{margin:10px 0 0;font-weight:900}
+.ideaCard .meta{margin-top:6px;color:var(--muted);font-size:13px;line-height:1.45}
+.ideaCard .tags{margin-top:10px;display:flex;gap:8px;flex-wrap:wrap}
+
+.toggle{
+  display:inline-flex;align-items:center;gap:10px;
+  padding:8px 10px;border-radius:12px;border:1px solid var(--stroke);
+  background:rgba(255,255,255,.03);
+  color:var(--muted);
+  font-weight:900;font-size:12px;cursor:pointer
+}
+.toggle input{accent-color:var(--blue)}
+
+.muted{color:var(--muted)}
+.right{justify-self:end}
+
+@media (max-width: 1060px){
+  .layout-terminal{grid-template-columns: 280px 1fr}
